  const def = new Date(Date.now() + 3600e3 * 3); def.setMinutes(0, 0, 0)
  const pad = (n: number) => String(n).padStart(2, '0')
  const [v, setV] = useState(`${def.getFullYear()}-${pad(def.getMonth() + 1)}-${pad(def.getDate())}T${pad(def.getHours())}:00`)
