input.command:
python3 - <<'EOF'
p='src/styles.css'
s=open(p).read()
s=s.replace("  .toolbar{padding:4px 4px}.pager-t{display:none}","  .toolbar{padding:4px 4px}.pager-t{display:none}.thread-pane .pager{display:none}")
open(p,'w').write(s)
EOF
cd ~ && dev-browser <<'EOF'
const page = await browser.getPage("mail9227b");
page.setDefaultTimeout(4000);
const errs=[];page.on("pageerror",e=>errs.push(String(e)));
await page.setViewportSize({width:1400,height:850});
await page.goto("http://localhost:9227/#/inbox"); await page.reload(); await page.waitForTimeout(500);
// keyboard: j, x, e
await page.keyboard.press("j"); await page.keyboard.press("x"); await page.keyboard.press("e");
const t1 = await page.locator(".toast").innerText();
await page.keyboard.press("z"); await page.waitForTimeout(200);
// snooze via row hover
await page.locator(".row").nth(2).hover();
await page.locator(".row").nth(2).getByLabel("Snooze").click();
await page.getByText("Tomorrow").first().click();
const snoozedRows = (await page.evaluate(()=>0));
await page.goto("http://localhost:9227/#/snoozed"); await page.waitForTimeout(300);
const sn = await page.locator(".row").count();
// search dropdown
await page.goto("http://localhost:9227/#/inbox");
await page.locator(".search input").click(); await page.keyboard.type("roadmap");
await page.waitForTimeout(300);
await saveScreenshot(await page.screenshot(),"sonnet-mail-search.png");
// dark
await page.keyboard.press("Escape");
await page.getByLabel("Toggle theme").click();
await page.getByText("Q4 roadmap").first().click(); await page.waitForTimeout(400);
await saveScreenshot(await page.screenshot(),"sonnet-mail-dark.png");
console.log(JSON.stringify({t1,sn,errs}));
EOF

